-- Preserve the M13-01 durable cancelled outcome.
create or replace function public.m13_05_event_projection(p_event public.audit_logs) returns jsonb language sql stable set search_path=pg_catalog,public as $$
 select jsonb_build_object('schemaVersion',1,'eventId',p_event.id,'organizationId',p_event.organization_id,'occurredAt',p_event.created_at,'eventClass',public.m13_05_event_class(p_event),'action',p_event.action,'outcome',case when p_event.outcome in ('intent','completed','failed','denied','cancelled') then p_event.outcome else 'unknown' end,'actorType',case when p_event.actor_type in ('user','service_account','system','ai','operator') then p_event.actor_type else 'unknown' end,'actorId',case when p_event.actor_id ~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then p_event.actor_id else null end,'resourceType',p_event.entity_type,'resourceId',case when p_event.entity_id ~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then p_event.entity_id else null end,'correlationId',p_event.correlation_id,'chainSequence',p_event.chain_sequence::text)
$$;
